    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_3,'speak',17,NULL,NULL,'از راننده بپرس این اتوبوس به ایستگاه قطار می‌رود یا نه.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"از راننده بپرس این اتوبوس به ایستگاه قطار می‌رود یا نه.","scenario_fa":"از راننده بپرس این اتوبوس به ایستگاه قطار می‌رود یا نه.","accepted":["Fährt dieser Bus zum Bahnhof?","Komme ich mit diesem Bus zum Bahnhof?"],"acceptedIntents":["Fährt dieser Bus zum Bahnhof?","Komme ich mit diesem Bus zum Bahnhof?"],"accepted_intents":["Fährt dieser Bus zum Bahnhof?","Komme ich mit diesem Bus zum Bahnhof?"],"input":"speech","evaluation":"stt","audioRequired":false,"textVisible":false,"scored":true,"independent":true}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',8));
