    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'word_order',15,v_t_9,NULL,NULL,'واژه‌ها را با لمس‌کردن به ترتیب درست بچین.',1,CAST('{"mode":"tap_tokens","input":"tap_tokens","scored":true,"independent":true,"tokens":["Bus","gleich","Der","fährt","los."],"answer":["Der","Bus","fährt","gleich","los."],"phase":"controlled_practice"}' AS JSON),JSON_OBJECT('contractMode','tap_tokens','typing',FALSE,'series',8));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'word_order',16,v_t_10,NULL,NULL,'واژه‌ها را با لمس‌کردن به ترتیب درست بچین.',1,CAST('{"mode":"tap_tokens","input":"tap_tokens","scored":true,"independent":true,"tokens":["wir","schon.","Ja,","sitzen"],"answer":["Ja,","wir","sitzen","schon."],"phase":"controlled_practice"}' AS JSON),JSON_OBJECT('contractMode','tap_tokens','typing',FALSE,'series',8));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',17,NULL,NULL,'پیش از سوارشدن بگو هنوز باید بلیت بخری.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"پیش از سوارشدن بگو هنوز باید بلیت بخری.","scenario_fa":"پیش از سوارشدن بگو هنوز باید بلیت بخری.","accepted":["Ich muss noch eine Fahrkarte kaufen.","Ich brauche zuerst eine Fahrkarte."],"acceptedIntents":["Ich muss noch eine Fahrkarte kaufen.","Ich brauche zuerst eine Fahrkarte."],"accepted_intents":["Ich muss noch eine Fahrkarte kaufen.","Ich brauche zuerst eine Fahrkarte."],"input":"speech","evaluation":"stt","audioRequired":false,"textVisible":false,"scored":true,"independent":true}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',8));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',18,NULL,NULL,'اتوبوس رسیده؛ بگو این خط شماست و حالا سوار می‌شوید.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"اتوبوس رسیده؛ بگو این خط شماست و حالا سوار می‌شوید.","scenario_fa":"اتوبوس رسیده؛ بگو این خط شماست و حالا سوار می‌شوید.","accepted":["Das ist unsere Linie, wir steigen jetzt ein.","Unser Bus ist da, jetzt steigen wir ein."],"acceptedIntents":["Das ist unsere Linie, wir steigen jetzt ein.","Unser Bus ist da, jetzt steigen wir ein."],"accepted_intents":["Das ist unsere Linie, wir steigen jetzt ein.","Unser Bus ist da, jetzt steigen wir ein."],"input":"speech","evaluation":"stt","audioRequired":false,"textVisible":false,"scored":true,"independent":true}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',8));
  ELSEIF v_count=1 THEN
    IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>46 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>72 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'de-fa-a1-series-0008' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match the validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  SELECT id INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=8;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
CALL import_nova_series_008()$$
